\copy (select c.match_id, c.mercado, c.seleccion, c.linea, c.linea_texto, c.cuota, c.momento, c.minutos_al_saque, m.kickoff_utc, m.home_goals, m.away_goals, m.home_goals_ht, m.away_goals_ht, m.home_corners, m.away_corners, m.status from futbol.cuota_historica c join matches m on m.match_id=c.match_id where c.fuente='betsapi' and c.momento='t60' and m.status in ('finished','FT','completed','played') ) to stdout with csv header
